                label="Fruit Trees"
                value={config.startingTrees}
                min={3}
                max={26}
                step={1}
                unit=" trees"
                accent="accent-emerald-400"
                onChange={(v) => onChangeConfig({ startingTrees: v })}
              />
              <SliderRow
                label="Starting Blue Blobs"
                value={config.startingBlue}
                min={2}
                max={45}
                step={1}
